//! The built-in film catalogue: real optical constants with their sources.
//!
//! Each entry is a refractiveindex.info database page (CC0), preferring a thin
//! film measurement where the database has one, with the paper it cites, the
//! wavelengths it covers, whether it describes a film, a bulk sample or a
//! crystal, and the constant `film_materials: Nominal` stands it in with
//! (its index at 0.55 µm). The data are generated by `tools/ri_import.py`
//! into `film_catalog_data.rs` and are the source's own numbers, so each knot
//! reproduces the source exactly.
//!
//! Tables answer outside their range with the end value (`Clamp`): under
//! `numerics: Permissive` that is flagged, under `Strict` refused.
//!
//! A scene carries its own catalogue (`Scene3::film_catalog`), which starts
//! from these entries or from anything the user adds, and a layer names its
//! entry by id. The constants in [`crate::thinfilm::materials`] are not this
//! catalogue: they are the nominal set the older presets and tests are built
//! from, and stay as they were.

use crate::material::DispersionFormula;
use crate::scene3::{Interpolation, OutOfRangePolicy, SpectralScalar};
use crate::thinfilm::{FilmFormula, FilmForm, FilmMaterial, NominalIndex, Provenance, SourceKind};
use serde::{Deserialize, Serialize};

#[path = "film_catalog_data.rs"]
mod data;

/// What the catalogue's data were read from, and when.
pub const RETRIEVED: &str = "2026-10-08, the refractiveindex.info database as packaged with Optiland 0.6.1";

/// One generated entry.
pub(crate) struct Entry {
    pub key: &'static str,
    pub name: &'static str,
    pub form: FilmForm,
    pub reference: &'static str,
    pub url: &'static str,
    pub note: &'static str,
    pub range_um: [f64; 2],
    pub nominal: [f64; 2],
    pub data: Data,
}

/// An entry's numbers, as the database gives them.
pub(crate) enum Data {
    /// `[λ µm, n, k]` rows.
    TableNk(&'static [[f64; 3]]),
    /// `[λ µm, n]` rows; k was not measured and is zero.
    TableN(&'static [[f64; 2]]),
    /// A refractiveindex.info formula for n (1, 2 or 5), and k as `[λ, k]`
    /// rows when the page gives them.
    Formula {
        formula: u8,
        coefficients: &'static [f64],
        k: Option<&'static [[f64; 2]]>,
    },
}

fn table(lambda_um: Vec<f64>, values: Vec<f64>) -> SpectralScalar {
    SpectralScalar::Tabulated {
        lambda_um,
        values,
        interpolation: Interpolation::Linear,
        out_of_range: OutOfRangePolicy::Clamp,
    }
}

fn material(e: &Entry) -> FilmMaterial {
    let (n, k, formula) = match &e.data {
        Data::TableNk(rows) => (
            table(rows.iter().map(|r| r[0]).collect(), rows.iter().map(|r| r[1]).collect()),
            table(rows.iter().map(|r| r[0]).collect(), rows.iter().map(|r| r[2]).collect()),
            None,
        ),
        Data::TableN(rows) => (
            table(rows.iter().map(|r| r[0]).collect(), rows.iter().map(|r| r[1]).collect()),
            SpectralScalar::Constant(0.0),
            None,
        ),
        Data::Formula { formula, coefficients, k } => {
            let coefficients = coefficients.to_vec();
            let f = match formula {
                1 => DispersionFormula::Sellmeier { coefficients },
                2 => DispersionFormula::Sellmeier2 { coefficients },
                5 => DispersionFormula::Cauchy { coefficients },
                other => unreachable!("the importer writes formulas 1, 2 and 5, not {other}"),
            };
            // `n` holds the formula sampled over its range, for readers that
            // know no formulas; the formula itself answers wherever it is valid.
            let [lo, hi] = e.range_um;
            let samples = 64;
            let xs: Vec<f64> = (0..=samples).map(|i| lo + (hi - lo) * i as f64 / samples as f64).collect();
            let ns = xs.iter().map(|&x| f.index(x)).collect();
            let k = match k {
                Some(rows) => table(rows.iter().map(|r| r[0]).collect(), rows.iter().map(|r| r[1]).collect()),
                None => SpectralScalar::Constant(0.0),
            };
            (table(xs, ns), k, Some(Box::new(FilmFormula { formula: f, range_um: e.range_um })))
        }
    };
    FilmMaterial {
        name: e.name.to_string(),
        n,
        k,
        formula,
        form: e.form,
        provenance: Some(Box::new(Provenance {
            source_kind: SourceKind::Database,
            reference: e.reference.to_string(),
            url: e.url.to_string(),
            license: "CC0-1.0".to_string(),
            retrieved: RETRIEVED.to_string(),
            range_um: Some(e.range_um),
            note: e.note.to_string(),
        })),
        nominal: Some(NominalIndex { n: e.nominal[0], k: e.nominal[1] }),
    }
}

/// Every built-in entry, as `(key, material)`, in catalogue order.
pub fn builtin() -> Vec<(&'static str, FilmMaterial)> {
    data::ENTRIES.iter().map(|e| (e.key, material(e))).collect()
}

/// The built-in entry `key` (`"silica"`, `"titania"`, `"silver"`, ...).
pub fn builtin_named(key: &str) -> Option<FilmMaterial> {
    data::ENTRIES.iter().find(|e| e.key == key).map(material)
}

/// One entry of a scene's film catalogue.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FilmCatalogEntry {
    pub id: u32,
    pub material: FilmMaterial,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_entry_builds_and_says_where_it_came_from() {
        let all = builtin();
        assert_eq!(all.len(), 17);
        for (key, m) in &all {
            let p = m.provenance.as_ref().expect("provenance");
            assert_eq!(p.source_kind, SourceKind::Database, "{key}");
            assert!(p.url.starts_with("https://refractiveindex.info/"), "{key}");
            assert!(!p.reference.is_empty(), "{key}");
            let [lo, hi] = p.range_um.unwrap();
            assert!(lo < 0.56 && hi > 0.56, "{key} covers the visible: {lo}..{hi}");
            let n = m.index_at(0.55).unwrap();
            assert!(n.re > 0.0 && n.im >= 0.0 && n.is_finite(), "{key}: {n:?}");
            assert!(m.covers(0.55));
            // The nominal is the index at 0.55 um.
            let nom = m.nominal_index();
            assert!((nom.re - n.re).abs() < 1e-12 && (nom.im - n.im).abs() < 1e-12, "{key}: {nom:?} vs {n:?}");
        }
    }

    #[test]
    fn a_formula_answers_inside_its_range_and_the_table_beyond_it() {
        let hafnia = builtin_named("hafnia").unwrap();
        let f = hafnia.formula.as_ref().unwrap();
        // Al-Kuhaili: n = 1.875 + 6.28e-3 / λ² + 5.80e-4 / λ⁴.
        let at = |l: f64| 1.875 + 6.28e-3 * l.powi(-2) + 5.80e-4 * l.powi(-4);
        for l in [0.2, 0.55, 1.3, 2.0] {
            assert!((hafnia.index_at(l).unwrap().re - at(l)).abs() < 1e-14, "{l}");
        }
        assert_eq!(f.range_um, [0.2, 2.0]);
        assert!(!hafnia.covers(2.5));
        // Past the range the sampled curve clamps to its end.
        assert!((hafnia.index_at(2.5).unwrap().re - at(2.0)).abs() < 1e-14);
    }
}
